      function (v) { return 'Dos resistencias en paralelo dan $R = \\dfrac{R_1R_2}{R_1 + R_2}$. Si $R_1 = ' + v.R1 + ' \\pm ' + v.d1 + '\\ \\Omega$ y $R_2 = ' + v.R2 + ' \\pm ' + v.d2 + '\\ \\Omega$, ¿cuál es el error máximo de $R$?'; },
