      function (v) { return 'La potencia en una resistencia es $P = I^2R$. Con $I = ' + v.I + ' \\pm ' + v.dI + '$ A y $R = ' + v.R + ' \\pm ' + v.dR + '\\ \\Omega$, estima el error máximo de $P$.'; },
